import sqlite3 from "sqlite3";

const dbPath = "/home/user/qwik-app/activity.db";

// Create a single database connection
const db = new sqlite3.Database(dbPath);

// Promisify database operations
export const dbRun = (sql: string, params: any[] = []): Promise<void> => {
  return new Promise((resolve, reject) => {
    db.run(sql, params, function (err) {
      if (err) reject(err);
      else resolve();
    });
  });
};

export const dbGet = <T>(sql: string, params: any[] = []): Promise<T | undefined> => {
  return new Promise((resolve, reject) => {
    db.get(sql, params, (err, row) => {
      if (err) reject(err);
      else resolve(row as T);
    });
  });
};

export const dbAll = <T>(sql: string, params: any[] = []): Promise<T[]> => {
  return new Promise((resolve, reject) => {
    db.all(sql, params, (err, rows) => {
      if (err) reject(err);
      else resolve(rows as T[]);
    });
  });
};

// Initialize database table
let initPromise: Promise<void> | null = null;

export const initDb = (): Promise<void> => {
  if (initPromise) return initPromise;

  initPromise = (async () => {
    await dbRun(`
      CREATE TABLE IF NOT EXISTS ActivityLog (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        path TEXT NOT NULL,
        method TEXT NOT NULL,
        ip TEXT NOT NULL,
        timestamp TEXT NOT NULL,
        duration_ms INTEGER NOT NULL
      )
    `);
  })();

  return initPromise;
};

export interface ActivityLog {
  id: number;
  path: string;
  method: string;
  ip: string;
  timestamp: string;
  duration_ms: number;
}

export async function logActivity(
  path: string,
  method: string,
  ip: string,
  timestamp: string,
  duration_ms: number,
): Promise<void> {
  await initDb();
  await dbRun(
    "INSERT INTO ActivityLog (path, method, ip, timestamp, duration_ms) VALUES (?, ?, ?, ?, ?)",
    [path, method, ip, timestamp, duration_ms],
  );
}

export async function getStats(): Promise<{
  total_requests: number;
  average_duration_ms: number;
}> {
  await initDb();
  const statsRow = await dbGet<{
    total_requests: number;
    average_duration_ms: number | null;
  }>(
    "SELECT COUNT(*) as total_requests, AVG(duration_ms) as average_duration_ms FROM ActivityLog",
  );

  const total_requests = statsRow?.total_requests || 0;
  const raw_avg = statsRow?.average_duration_ms || 0;
  const average_duration_ms = raw_avg ? parseFloat(raw_avg.toFixed(2)) : 0;

  return {
    total_requests,
    average_duration_ms,
  };
}

export async function getLogs(): Promise<ActivityLog[]> {
  await initDb();
  return dbAll<ActivityLog>(
    "SELECT id, path, method, ip, timestamp, duration_ms FROM ActivityLog ORDER BY timestamp DESC",
  );
}

import { type RequestHandler } from "@builder.io/qwik-city";
import { logActivity } from "../db";

export const onRequest: RequestHandler = async ({ url, method, clientConn, next }) => {
  const path = url.pathname;
  const matches = path.startsWith("/api/") || path.startsWith("/admin/");

  if (!matches) {
    await next();
    return;
  }

  const startTime = performance.now();
  const timestamp = new Date().toISOString();

  try {
    await next();
  } finally {
    const duration_ms = Math.round(performance.now() - startTime);
    const ip = clientConn.ip || "127.0.0.1";
    try {
      await logActivity(path, method, ip, timestamp, duration_ms);
    } catch (err) {
      console.error("Failed to log activity:", err);
    }
  }
};

import { type RequestHandler } from "@builder.io/qwik-city";

export const onGet: RequestHandler = async ({ json }) => {
  json(200, { ping: "pong" });
};

import { type RequestHandler } from "@builder.io/qwik-city";

export const onGet: RequestHandler = async ({ url, json }) => {
  const delayParam = url.searchParams.get("delay");
  const delay = delayParam ? parseInt(delayParam, 10) : 0;

  if (delay > 0) {
    await new Promise((resolve) => setTimeout(resolve, delay));
  }

  json(200, { delayed: true, delay });
};

import { component$ } from "@builder.io/qwik";

export default component$(() => {
  return (
    <div>
      <h1>Admin Dashboard</h1>
    </div>
  );
});

import { component$ } from "@builder.io/qwik";

export default component$(() => {
  return (
    <div>
      <h1>Public Page</h1>
    </div>
  );
});

import { component$ } from "@builder.io/qwik";
import { routeLoader$, type RequestHandler } from "@builder.io/qwik-city";
import { getStats, getLogs } from "../../../db";

export const onGet: RequestHandler = async ({ url, json }) => {
  if (url.searchParams.get("format") === "json") {
    const stats = await getStats();
    const logs = await getLogs();
    json(200, {
      total_requests: stats.total_requests,
      average_duration_ms: stats.average_duration_ms,
      logs,
    });
  }
};

export const useActivityData = routeLoader$(async () => {
  const stats = await getStats();
  const logs = await getLogs();
  return {
    total_requests: stats.total_requests,
    average_duration_ms: stats.average_duration_ms,
    logs,
  };
});

export default component$(() => {
  const data = useActivityData();

  return (
    <div style={{ padding: "20px", fontFamily: "sans-serif" }}>
      <h1>Admin Activity</h1>
      <div>
        <strong>Total Requests:</strong>{" "}
        <span id="total-requests">{data.value.total_requests}</span>
      </div>
      <div>
        <strong>Average Duration (ms):</strong>{" "}
        <span id="average-duration">{data.value.average_duration_ms}</span>
      </div>
      <h2>Recent Logs</h2>
      <div id="logs-list">
        {data.value.logs.map((log) => (
          <div
            key={log.id}
            style={{
              padding: "8px",
              borderBottom: "1px solid #ccc",
              margin: "4px 0",
            }}
          >
            <strong>ID:</strong> {log.id} | <strong>Path:</strong> {log.path} |{" "}
            <strong>Method:</strong> {log.method} | <strong>IP:</strong> {log.ip} |{" "}
            <strong>Timestamp:</strong> {log.timestamp} |{" "}
            <strong>Duration:</strong> {log.duration_ms}ms
          </div>
        ))}
      </div>
    </div>
  );
});

